// Isolated regression controls: generated bytes only, no saves or services.
import test from 'node:test';
import assert from 'node:assert/strict';
import * as C from '../core/container.mjs';
import * as H from '../core/header.mjs';
import * as I from '../core/items.mjs';
import * as P from '../core/progress.mjs';

function system(records) {
  const bytes = new Uint8Array(C.SYSTEM_SIZE);
  const v = new DataView(bytes.buffer);
  records.forEach((r, i) => v.setUint32(0x34 + 4 * i, r, true));
  return bytes;
}
function hnt() {
  const bytes = new Uint8Array(C.HNT_SIZE);
  return C.hunterView(C.openHnt(bytes), 0);
}

test('system rejects overlapping records and immutable header aliases without mutation', () => {
  const stride = C.BLOCK_SIZE + 36;
  const first = 0x18cc78;
  const third = first + 2 * stride;
  for (const records of [
    [1, 1, 1], [0x3f, first + stride, third], [0x5b, first + stride, third],
    [first - 1, first + stride, third], [first, first, third], [first, first + 1, third],
    [first, first + C.BLOCK_SIZE, third], // blocks disjoint, second prefix overlaps first block
    [first, first + stride - 1, third], [first, first + stride, 0xffffffff],
  ]) {
    const bytes = system(records);
    const before = bytes.slice();
    assert.throws(() => C.openSystem(bytes), RangeError, records.join(','));
    assert.deepEqual(bytes, before);
  }
});

test('derived, adjacent and reordered record ranges stay writable and isolated', () => {
  const stride = C.BLOCK_SIZE + 36;
  // Historical documented coordinates are one positive shape, not magic origins in the parser.
  for (const records of [
    [0x18cc78, 0x2ac53c, 0x3cbe00],
    [0x18cc78 + 1, 0x18cc78 + 1 + stride, 0x18cc78 + 1 + 2 * stride],
    [0x3cbe00, 0x18cc78, 0x2ac53c],
  ]) {
    const bytes = system(records);
    const before = bytes.slice();
    const opened = C.openSystem(bytes);
    const slot = C.hunterView(opened, 0);
    H.writeName(slot, 'X');
    assert.equal(H.readName(slot), 'X');
    assert.equal(H.readName(C.hunterView(opened, 1)), '');
    assert.equal(H.readName(C.hunterView(opened, 2)), '');
    before[records[0] + 36] = 88;
    assert.deepEqual(bytes, before);
  }
});

test('hunter, palico and owner names preserve the accepted leading BOM code point', () => {
  const view = hnt();
  const cases = [
    [s => H.writeName(view, s), () => H.readName(view), H.NAME_OFF],
    [s => P.writePalicoName(view, 0, s), () => P.readPalicoName(view, 0), P.PALICO_GROUP_A_OFF],
    [s => P.writePalicoOwnerName(view, 0, s), () => P.readPalicoOwnerName(view, 0), P.PALICO_GROUP_A_OFF + 0x9c],
  ];
  for (const [write, read, off] of cases) {
    write('\uFEFFX');
    assert.deepEqual([...view.u8.slice(off, off + 5)], [0xef, 0xbb, 0xbf, 0x58, 0]);
    assert.equal(read(), '\uFEFFX');
    const before = view.u8.slice();
    write(read());
    assert.deepEqual(view.u8, before);
  }
});

test('preset rejects malformed UTF-16 before touching the image, including truncated suffix', () => {
  const view = hnt();
  for (const layout of ['legacy', 'v7']) {
    I.writeItemPresetName(view, layout, 0, 'sentinel');
    const before = view.u8.slice();
    for (const bad of ['\uD800', '\uDC00', '\uD800X', 'A'.repeat(42) + '\uD800']) {
      assert.throws(() => I.writeItemPresetName(view, layout, 0, bad), /surrogate/);
      assert.deepEqual(view.u8, before);
    }
    const paired = '\uD834\uDD1E';
    I.writeItemPresetName(view, layout, 0, paired);
    assert.equal(I.readItemPresetName(view, layout, 0), paired);
    I.writeItemPresetName(view, layout, 0, 'A'.repeat(40) + paired);
    assert.equal(I.readItemPresetName(view, layout, 0), 'A'.repeat(40));
    I.writeItemPresetName(view, layout, 0, 'A'.repeat(38) + paired);
    assert.equal(I.readItemPresetName(view, layout, 0), 'A'.repeat(38) + paired);
  }
});
